/**
 * Android SDK tools on the Host: where the device panel looks for adb and the emulator, how a candidate resolves to an
 * executable file without a shell, and installing Google's platform-tools into the panel's own directory.
 * Generated by ttoken/apply-brand.mjs from ttoken/device/src/platform-tools.ts; edit it there.
 */

import { randomUUID } from 'node:crypto'
import { accessSync, constants, existsSync, statSync, type Stats } from 'node:fs'
import { mkdir, rename, rm, writeFile } from 'node:fs/promises'
import { homedir } from 'node:os'
import { posix, win32 } from 'node:path'
import { scrubbedParentEnv } from '@deepseek-ai/dsh-subprocess'
import { execa } from 'execa'

/** Android SDK tool the panel starts. */
export type SdkTool = 'adb' | 'emulator'

/** Largest platform-tools archive the panel downloads; Google's archives are about 10 MB. */
export const MAX_PLATFORM_TOOLS_BYTES = 268_435_456

/** The platform-tools install failed; the message names the step. */
export class PlatformToolsInstallError extends Error {
  override name = 'PlatformToolsInstallError'
}

/**
 * Read one environment variable. Windows names are case-insensitive, so `Path` answers for `PATH` there.
 * @param env - environment to read.
 * @param name - variable name in upper case.
 * @param platform - Host platform.
 * @returns the value, or undefined when unset.
 */
function envValue(env: NodeJS.ProcessEnv, name: string, platform: NodeJS.Platform): string | undefined {
  if (platform !== 'win32') return env[name]
  const key = Object.keys(env).find(candidate => candidate.toUpperCase() === name)
  return key === undefined ? undefined : env[key]
}

/**
 * Path functions of one Host platform.
 * @param platform - Host platform.
 * @returns Windows path functions on Windows, POSIX ones elsewhere.
 */
function pathsOf(platform: NodeJS.Platform): typeof posix {
  return platform === 'win32' ? win32 : posix
}

/**
 * Read a file's status.
 * @param path - file path.
 * @returns the status, or undefined when the path is missing or cannot be read.
 */
function statOf(path: string): Stats | undefined {
  try {
    return statSync(path)
  } catch (unreadable) {
    // A missing path, or a PATH entry that is a file or unreadable, holds no executable; the search moves on.
    void unreadable
    return undefined
  }
}

/**
 * Whether a path names a file the Host can run.
 * @param path - file path.
 * @param platform - Host platform; Windows runs a file by its extension, other platforms need the execute permission.
 * @returns true for a runnable file.
 */
function isExecutableFile(path: string, platform: NodeJS.Platform): boolean {
  if (statOf(path)?.isFile() !== true) return false
  if (platform === 'win32') return true
  try {
    accessSync(path, constants.X_OK)
  } catch (notExecutable) {
    // A file without the execute permission cannot start; the search moves on.
    void notExecutable
    return false
  }
  return true
}

/**
 * Resolve a command to an executable file the way a shell would, without starting one: a path is kept when it names a
 * runnable file, and a bare name is searched on PATH, with the PATHEXT extensions on Windows. Windows otherwise runs an
 * unresolved name through `cmd.exe`, which reports a missing program as an ordinary failed run.
 * @param command - executable name or path.
 * @param env - environment holding PATH and PATHEXT.
 * @param platform - Host platform.
 * @returns the executable's path, or undefined when no runnable file matches.
 */
export function resolveExecutable(
  command: string, env: NodeJS.ProcessEnv = process.env, platform: NodeJS.Platform = process.platform,
): string | undefined {
  const paths = pathsOf(platform)
  const extensions = platform === 'win32' && paths.extname(command) === ''
    ? (envValue(env, 'PATHEXT', platform) ?? '.COM;.EXE;.BAT;.CMD').split(';').filter(extension => extension !== '')
    : ['']
  const named = command.includes('/') || (platform === 'win32' && command.includes('\\'))
  const directories = named
    ? ['']
    : (envValue(env, 'PATH', platform) ?? '').split(paths.delimiter)
      .map(directory => directory.replace(/^"(.*)"$/, '$1'))
      .filter(directory => directory !== '')
  return directories
    .flatMap(directory => extensions.map(extension => `${directory === '' ? command : paths.join(directory, command)}${extension}`))
    .find(path => isExecutableFile(path, platform))
}

/** Where to look for an SDK tool beyond the configured command. */
export interface SdkToolLocations {
  /** Environment that names the SDK and the package-manager folders. */
  readonly env?: NodeJS.ProcessEnv
  /** Host platform. */
  readonly platform?: NodeJS.Platform
  /** Host home directory. */
  readonly home?: string
  /** Directory the panel installs platform-tools into; empty when the panel installs none. */
  readonly installDirectory?: string
}

/**
 * The executables to try for an SDK tool, in order: the configured one, then, when the configuration names the bare
 * tool, the tool inside each Android SDK (`ANDROID_HOME`, `ANDROID_SDK_ROOT`, and the directory Android Studio
 * installs the SDK in, which Android Studio does not put on PATH). For adb, the list goes on with the folders package
 * managers link programs into, which a running app may not have on PATH yet (winget, Scoop, and Chocolatey on
 * Windows; Homebrew on macOS), and ends with the platform-tools the panel installed. Candidates resolve when a run
 * starts, so a tool installed while the app runs is found.
 * @param tool - the SDK tool.
 * @param configured - the configured executable name or path.
 * @param locations - environment, platform, home, and the panel's install directory.
 * @returns executables in the order to try them.
 */
export function sdkToolCommands(tool: SdkTool, configured: string, locations: SdkToolLocations = {}): string[] {
  if (configured !== tool) return [configured]
  const env = locations.env ?? process.env
  const platform = locations.platform ?? process.platform
  const home = locations.home ?? homedir()
  const paths = pathsOf(platform)
  const local = envValue(env, 'LOCALAPPDATA', platform)
  const studio = platform === 'win32'
    ? local === undefined ? undefined : paths.join(local, 'Android', 'Sdk')
    : platform === 'darwin' ? paths.join(home, 'Library', 'Android', 'sdk') : paths.join(home, 'Android', 'Sdk')
  const file = platform === 'win32' ? `${tool}.exe` : tool
  const directory = tool === 'adb' ? 'platform-tools' : 'emulator'
  const sdk = [envValue(env, 'ANDROID_HOME', platform), envValue(env, 'ANDROID_SDK_ROOT', platform), studio]
    .filter((root): root is string => root !== undefined && root !== '')
    .map(root => paths.join(root, directory, file))
  if (tool === 'emulator') return [...new Set([configured, ...sdk])]
  const programData = envValue(env, 'PROGRAMDATA', platform)
  const linked = platform === 'win32'
    ? [
      local === undefined ? undefined : paths.join(local, 'Microsoft', 'WinGet', 'Links'),
      paths.join(home, 'scoop', 'shims'),
      programData === undefined ? undefined : paths.join(programData, 'chocolatey', 'bin'),
    ]
    : platform === 'darwin' ? ['/opt/homebrew/bin', '/usr/local/bin'] : []
  const installed = locations.installDirectory === undefined || locations.installDirectory === ''
    ? []
    : [paths.join(locations.installDirectory, 'platform-tools', file)]
  return [...new Set([
    configured,
    ...sdk,
    ...linked.filter((folder): folder is string => folder !== undefined).map(folder => paths.join(folder, file)),
    ...installed,
  ])]
}

/**
 * Google's archive of the latest platform-tools for a Host platform.
 * @param platform - Host platform.
 * @returns the archive URL, or undefined where Google publishes none.
 */
export function platformToolsUrl(platform: NodeJS.Platform): string | undefined {
  const os = platform === 'win32' ? 'windows' : platform === 'darwin' ? 'darwin' : platform === 'linux' ? 'linux' : undefined
  return os === undefined ? undefined : `https://dl.google.com/android/repository/platform-tools-latest-${os}.zip`
}

/**
 * The program that unpacks a zip archive on the Host: the `tar` Windows 10 and later ship in System32, the `tar`
 * macOS ships, and `unzip` elsewhere.
 * @param archive - zip archive path.
 * @param destination - directory to unpack into.
 * @param env - environment holding `SystemRoot` on Windows.
 * @param platform - Host platform.
 * @returns the executable and its arguments.
 */
export function unzipCommand(
  archive: string, destination: string, env: NodeJS.ProcessEnv, platform: NodeJS.Platform,
): { readonly command: string; readonly args: readonly string[] } {
  if (platform === 'win32') {
    const system = envValue(env, 'SYSTEMROOT', platform) ?? 'C:\\Windows'
    return { command: win32.join(system, 'System32', 'tar.exe'), args: ['-xf', archive, '-C', destination] }
  }
  if (platform === 'darwin') return { command: '/usr/bin/tar', args: ['-xf', archive, '-C', destination] }
  return { command: 'unzip', args: ['-q', archive, '-d', destination] }
}

/** One platform-tools install. */
export interface PlatformToolsInstall {
  /** Directory that receives `platform-tools`; created when missing. */
  readonly directory: string
  /** Deadline in milliseconds for the download and for unpacking. */
  readonly timeoutMs: number
  /** Host platform. */
  readonly platform?: NodeJS.Platform
  /** Environment of the unpacking program. */
  readonly env?: NodeJS.ProcessEnv
  /** HTTP client of the download. */
  readonly fetch?: typeof fetch
}

/**
 * Download Google's latest platform-tools for the Host and unpack them into `<directory>/platform-tools`. An earlier
 * copy is replaced only after the new archive unpacked with an adb inside it.
 * @param install - target directory, deadline, and Host.
 * @param signal - cancellation of the install.
 * @returns the installed adb path.
 * @throws PlatformToolsInstallError naming the step that failed; the signal's reason when cancelled.
 */
export async function installPlatformTools(install: PlatformToolsInstall, signal: AbortSignal): Promise<string> {
  const platform = install.platform ?? process.platform
  const url = platformToolsUrl(platform)
  if (url === undefined) throw new PlatformToolsInstallError(`Google publishes no platform-tools for ${platform}`)
  const paths = pathsOf(platform)
  const deadline = AbortSignal.any([signal, AbortSignal.timeout(install.timeoutMs)])
  await mkdir(install.directory, { recursive: true })
  const work = paths.join(install.directory, `.install-${randomUUID()}`)
  await mkdir(work)
  try {
    const archive = paths.join(work, 'platform-tools.zip')
    let bytes: Uint8Array
    try {
      bytes = await download(install.fetch ?? fetch, url, deadline)
    } catch (error) {
      // The caller's cancellation keeps its own reason; a network failure or the deadline stays an install failure.
      signal.throwIfAborted()
      throw error
    }
    await writeFile(archive, bytes)
    const unzip = unzipCommand(archive, work, install.env ?? process.env, platform)
    const result = await execa(unzip.command, unzip.args, {
      env: install.env ?? scrubbedParentEnv(), extendEnv: false, stdin: 'ignore', reject: false, cancelSignal: deadline,
    })
    signal.throwIfAborted()
    if (result.exitCode !== 0) {
      const reason = result.stderr.split(/\r?\n/).find(line => line.trim() !== '') ?? result.shortMessage
      throw new PlatformToolsInstallError(`The archive could not be unpacked: ${reason}`)
    }
    const file = platform === 'win32' ? 'adb.exe' : 'adb'
    const unpacked = paths.join(work, 'platform-tools')
    if (!existsSync(paths.join(unpacked, file))) throw new PlatformToolsInstallError('The archive holds no adb')
    const target = paths.join(install.directory, 'platform-tools')
    if (existsSync(target)) await rename(target, paths.join(work, 'previous'))
    await rename(unpacked, target)
    return paths.join(target, file)
  } finally {
    await rm(work, { recursive: true, force: true })
  }
}

/**
 * Read a download into memory, refusing one larger than {@link MAX_PLATFORM_TOOLS_BYTES}.
 * @param client - HTTP client.
 * @param url - archive URL.
 * @param signal - cancellation and deadline.
 * @returns the archive bytes.
 * @throws PlatformToolsInstallError for a failed or cancelled request, an error status, or an oversized body.
 */
async function download(client: typeof fetch, url: string, signal: AbortSignal): Promise<Uint8Array> {
  try {
    const response = await client(url, { signal })
    if (!response.ok || response.body === null) {
      throw new PlatformToolsInstallError(`Google answered HTTP ${response.status} for the platform-tools download`)
    }
    const reader = response.body.getReader()
    const chunks: Uint8Array[] = []
    let total = 0
    for (;;) {
      const { done, value } = await reader.read()
      if (done) return Buffer.concat(chunks)
      total += value.byteLength
      if (total > MAX_PLATFORM_TOOLS_BYTES) {
        await reader.cancel()
        throw new PlatformToolsInstallError(`The download is larger than ${MAX_PLATFORM_TOOLS_BYTES} bytes`)
      }
      chunks.push(value)
    }
  } catch (error) {
    if (error instanceof PlatformToolsInstallError) throw error
    throw new PlatformToolsInstallError(`The download from Google failed: ${error instanceof Error ? error.message : String(error)}`)
  }
}
